                        .content("""
                                {"measurementKey":"M-12","instrumentId":"INS-1",
                                 "measuredAt":"2026-06-01T00:00:00Z","reading":"1",
                                 "lowerLimit":"0","upperLimit":"9","submittedBy":""}"""))
                .andExpect(status().isBadRequest());
    }
}

